        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        ListNode head = null, tail = null;
        for (int i = 0; i < n; i++) {
            in.nextToken();
            ListNode node = new ListNode((long) in.nval);
            if (tail == null) head = node;
            else tail.next = node;
            tail = node;
        }
        StringBuilder sb = new StringBuilder();
        int k = 0;
        for (ListNode p = removeDuplicated(head); p != null; p = p.next) {
            if (k > 0) sb.append(' ');
            sb.append(p.val);
            k++;
